// Datos de ejemplo para la demo: se crean por API, con su fecha original.
// Sirven para ensayar los flujos (confirmacion, recibo, recordatorios, cierre...).
const euros = (n) => Number(n).toFixed(2);

const base = {
  producto: 'Botín piel marrón',
  talla: '38',
  forma_pago: 'bizum',
};

const clientes = [
  { nombre: 'Cliente Demo Abono', email: 'demo.abono@example.com', telefono: '600 111 001', precio: 89.9, abono: 20, dias: 0 },
  { nombre: 'Cliente Demo Pendiente', email: 'demo.pendiente@example.com', telefono: '600 111 002', precio: 64.5, abono: 10, dias: 0 },
  { nombre: 'Cliente Demo Liquidado', email: 'demo.liquidado@example.com', telefono: '600 111 003', precio: 45, abono: 45, dias: 0 },
  { nombre: 'Cliente Demo Vencido', email: 'demo.vencido@example.com', telefono: '600 111 004', precio: 55, abono: 5, dias: 120 },
  { nombre: 'Cliente Demo Proximo', email: 'demo.proximo@example.com', telefono: '600 111 005', precio: 72, abono: 15, dias: 83 },
];

const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());

const fechaMenos = (dias) => {
  const f = new Date(hoy + 'T00:00:00Z');
  f.setUTCDate(f.getUTCDate() - dias);
  return f.toISOString().slice(0, 10);
};

return clientes.map((c) => ({
  json: {
    tipo: 'demo',
    apartado: {
      cliente: c.nombre,
      email: c.email,
      telefono: c.telefono,
      producto: base.producto,
      talla: base.talla,
      precio: euros(c.precio),
      abono_inicial: euros(c.abono),
      forma_pago: base.forma_pago,
      fecha: fechaMenos(c.dias),
    },
    nota: c.dias === 0 ? 'creado hoy' : 'creado hace ' + c.dias + ' dias',
  },
}));

// Resumen de la demo: que se ha creado y como queda la tienda.
// La API da las fechas como AAAA-MM-DD; en los mensajes van como dia/mes/año.
const fechaES = (f) => {
  const t = String(f ?? '').split('-');
  return t.length === 3 ? t[2].slice(0, 2) + '/' + t[1] + '/' + t[0] : String(f ?? '');
};
const creados = $('Crear apartado de demo').all().map((i) => i.json).filter((a) => a && a.id !== undefined);
const resumen = $input.first().json ?? {};
// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const cuerpo = [
  'Datos de demo creados en la tienda:',
  '',
].concat(creados.map((c) => '  - #' + c.id + ' ' + c.cliente + ' | ' + c.producto + ' | pendiente ' + Number(c.pendiente).toFixed(2) + ' EUR | limite ' + fechaES(c.fecha_limite))).concat([
  '',
  'Estado de la tienda: ' + (resumen.activo ?? 0) + ' activos, ' + (resumen.liquidado ?? 0) + ' liquidados, ' + (resumen.vencido ?? 0) + ' vencidos.',
]).join('\n');

return [{
  json: {
    canal: 'email',
    email: emailTienda,
    asunto: 'Datos de demo creados',
    cuerpo,
    cuerpo_html: '<p>' + escapar(cuerpo).replace(/\n/g, '<br>') + '</p>',
    creados: creados.length,
  },
}];
